    with open(f) as fp:
        data=json.load(fp)
        alerts.extend(data)
# collect unique alertnames and count firing
summary={}
for a in alerts:
    name=a['labels'].get('alertname')
    state=a.get('state')
    if name not in summary:
        summary[name]={'firing':0,'pending':0,'inactive':0}
    summary[name][state]=summary[name].get(state,0)+1
print('Alert summary:')
for n,st in summary.items():
    print(n, st)
PY"]}

